import re

def parse_duration(text: str) -> int:
    if not text or not re.match(r'^ ( [1-9] |\b0\b) \d*[hms](\b[1-9]\b|\b0\b)\d*[hms])*$', text):
        raise ValueError

    total_seconds = 0
    parts = re.findall(r'\d+[hms]', text)

    for part in parts:
        number, unit = int(part[:-1]), part[-1]
        if unit not in {'h': 3600, 'm': 60, 's': 1}:
            raise ValueError
        total_seconds += number * {'h': 3600, 'm': 60, 's': 1}[unit]

    return total_seconds

import re

UNIT_TO_SECONDS = {'h': 3600, 'm': 60, 's': 1}

def parse_duration(text: str) -> int:
    if not text:
        raise ValueError

    pattern = r'^([0-9]+h)?([0-9]+m)?([0-9]+s)?$'
    match = re.match(pattern, text)
    if not match:
        raise ValueError

    total_seconds = 0
    for i, unit in enumerate(('h', 'm', 's')):
        if match.group(i + 1):
            total_seconds += int(match.group(i + 1)[:-1]) * UNIT_TO_SECONDS[unit]

    return total_seconds

import re

def parse_duration(text):
    if not text:
        raise ValueError('Empty input')
    pattern = r'^([0-9]+)h([0-9]+)m([0-9]+)s$'
    match = re.match(pattern, text)
    if not match:
        raise ValueError('Invalid format')
    hours, minutes, seconds = map(int, match.groups())
    return hours * 3600 + minutes * 60 + seconds

