        raise TypeError('Both arguments must be of type str')
    normalized_a = a.replace(' ', '').lower()
    normalized_b = b.replace(' ', '').lower()
    return sorted(normalized_a) == sorted(normalized_b)

def is_anagram(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError('Both arguments must be strings')
    normalized_a = ''.join(sorted(a.lower().replace(' ', '')))
    normalized_b = ''.join(sorted(b.lower().replace(' ', '')))
    return normalized_a == normalized_b

