def title_case(s):
    small_words = {'a', 'an', 'the', 'of', 'in'}
    words = s.split()
    for i, word in enumerate(words):
        if word.lower() in small_words and i != 0:
            words[i] = word.lower()
        else:
            words[i] = word.capitalize()
    return ' '.join(words)

