import re

ROMAN_NUMERALS = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
}

def roman_to_int(s):
    if not s:
        raise ValueError('Input string is empty')
    if not s.isupper():
        raise ValueError('Input string is not uppercase')
    if not re.match(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$', s):
        raise ValueError('Input string is not a valid Roman numeral')

    total = 0
    prev_value = 0
    for char in s[::-1]:
        value = ROMAN_NUMERALS[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value

    return total

import re

def parse_kv(text):
    pattern = r'^\s*([a-z_]+)\s*=\s*(.*)\s*$'
    result = {}
    seen_keys = set()

    for pair in text.split(';'):
        pair = pair.strip()
        if pair:
            match = re.match(pattern, pair)
            if not match:
                raise ValueError(f'Invalid pair: {pair}')
            key, value = match.groups()
            if key in seen_keys:
                raise ValueError(f'Duplicate key: {key}')
            seen_keys.add(key)
            result[key] = value

    return result

from collections import OrderedDict
class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError('Capacity must be at least 1')
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

