        if isinstance(item, list):
            for subitem in item:
                out.append(subitem)
        else:
            out.append(item)
    return out

def moving_average(xs, k):
    if k < 1:
        raise ValueError('k must be at least 1')
    return [sum(xs[i:i + k]) / k for i in range(len(xs) - k + 1)]

