class Inventory:
    def __init__(self):
        self.items = {}

    def add(self, name, qty, unit_price):
        if qty <= 0 or unit_price < 0:
            raise ValueError('Invalid quantity or unit price')
        if name in self.items:
            self.items[name]['qty'] += qty
            self.items[name]['unit_price'] = unit_price
        else:
            self.items[name] = {'qty': qty, 'unit_price': unit_price}

    def remove(self, name, qty):
        if name not in self.items:
            raise KeyError('Item not found')
        if qty <= 0 or qty > self.items[name]['qty']:
            raise ValueError('Invalid quantity')
        self.items[name]['qty'] -= qty
        if self.items[name]['qty'] == 0:
            del self.items[name]

    def quantity(self, name):
        return self.items.get(name, {}).get('qty', 0)

    def total_value(self):
        return sum(item['qty'] * item['unit_price'] for item in self.items.values())

